effect.shader:
vec4 tex2(vec2 p){ return texture2DCv(inputImg2.texture, p); }
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec4 a = tex(uv);
vec4 b = tex2(uv);
float dx = abs(fract(uv.x * max(cols, 1.0)) - 0.5) * 2.0;
float dy = abs(fract(uv.y * max(rows, 1.0)) - 0.5) * 2.0;
float d = max(dx, dy);
float p = clamp(progress, 0.0, 1.0);
float soft = max(feather, 0.001);
float m = 1.0 - smoothstep(p - soft, p + soft, d);
float k = m * mixAmt;
gl_FragColor = vec4(mix(a.rgb, b.rgb, k), mix(a.a, b.a, k));
}
